						// 婵犵數濮烽弫鍛婃叏閻戣棄鏋侀柛娑橈攻閸欏繘鏌ｉ幋锝嗩棄闁哄绶氶弻鐔兼⒒鐎靛壊妲紒鐐劤椤兘寮婚敐澶婃婵炲棛鍋撶粊鍙夌節閵忥絽鐓愰柛鏃€娲滅划璇测槈閵忥紕鍘告繝銏ｆ硾鐎涒晝娑甸崼鏇熺叆婵炴垶鐟уú瀛樻叏婵犲洨绱伴柕鍥ㄥ姍楠炴帡骞嬪鍐╃€抽梻鍌欑閹诧紕婀佺紓渚囧枟閻熴儵鎮鹃悜鑺ユ櫜闁割偁鍨婚弶绋库攽閻愭潙鐏﹂柣鐔濆洤鍌ㄩ梺顒€绉甸埛鎴︽煕閿旇骞栧ù婊呭亾閵囧嫰濡搁妷锕€娅ч梺閫炲苯澧慨妯稿姂瀹曟螣閾忚娈鹃梺纭呮彧缁犳垶鍎梻渚€娼чˇ浠嬪窗濡ゅ啠鍋撻棃娑氱劯婵﹥妞藉Λ鍐ㄢ槈濮橆剦鏆繝纰樻閸嬪懘鎮疯缁傚秹骞栨担璇℃濠电偞鍨剁敮妤呭棘閳ь剚淇婇悙顏勨偓鏍哄澶婄；闁圭偓鐣禍婊堟煏婢舵盯妾悘蹇斿缁辨帡寮崒姘亪閻庢鍠楅幐鎶藉箖閵忕妴娲敂閸滀讲鍋撳澶嬧拻濞达絽鎲￠崯鐐电磼鐎ｎ偄鐏撮柡浣稿暣閺佸啴宕掑顒€浜堕梻浣圭湽閸ㄥ綊骞夐敓鐘茬厱闁硅揪闄勯崑锝夋煕閵夘垳宀涢柛瀣尭閻ｇ兘宕堕敐鍛婵犵數濮电喊宥夊磹閸洘鐓熼柟閭﹀灡绾墽鎮顒夋富闁靛牆妫欓悡銉х磼婢跺灏﹂柛鈺冨仱楠炲鏁傞挊澶嗗亾閻戣姤鐓犵痪鏉垮船婢ь垶鏌熼懠璺轰汗缂佽鲸鎸荤粭鐔煎炊瑜庨悘鎾寸節閻㈤潧浜归柛瀣崌閹鎲撮崟顒傤槬濠电姭鍋撻梺顒€绉寸粻鏌ユ煕閺囥劌澧伴柣鐔活潐閵囧嫰寮介妸褋鈧帞绱?
						// Result data is returned by IONVM_FILTER_RESULT (0xce).
						nvmeCPL.dword[0] = 0;
						nvmeCPL.specific = 0x0;
						set_auto_nvme_cpl(nvmeCmd.cmdSlotTag, nvmeCPL.specific, nvmeCPL.statusFieldWord);
